#!/usr/bin/env bash
# third-party/generate-notices.sh — aggregate THIRD_PARTY_NOTICES.md (design-docs/13 §6.1, D8).
#
# Produces a single, human-readable Third-Party Notices file from the lock.json
# baseline + the per-component NOTICE files under third-party/NOTICES/. This is
# the redistribution-ready attribution bundle.
#
# The aggregated file is a build artifact (git-ignored); regenerate with
# `make notices` before each release. Source of truth is lock.json + NOTICES/.
set -uo pipefail

ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
cd "$ROOT"

LOCK="third-party/lock.json"
OUT="THIRD_PARTY_NOTICES.md"

if ! command -v jq >/dev/null 2>&1; then
  echo "generate-notices.sh: jq is required" >&2
  exit 2
fi
if [ ! -f "$LOCK" ]; then
  echo "generate-notices.sh: missing $LOCK" >&2
  exit 2
fi

{
  printf '# Third-Party Notices\n\n'
  printf 'This product (Mora) includes third-party software and reference specifications.\n'
  printf 'Below is the attribution for each component, derived from `third-party/lock.json`.\n'
  printf 'Regenerate with `make notices`.\n\n'
  printf 'Mora itself is licensed under the Apache License, Version 2.0 (see `./LICENSE`).\n\n'
  printf '## Direct dependencies\n\n'
  printf '| Ecosystem | Component | Version | License | Digest | Source |\n'
  printf '|---|---|---|---|---|---|\n'
  jq -r '.components[] | select(.ecosystem != "reference") | "| \(.ecosystem) | \(.name) | \(.version) | \(.license) | `\(.digest)` | \(.source_url) |"' "$LOCK"
  printf '\n## Reference specifications\n\n'
  printf '| Component | Version | Status | License | Source | ADR |\n'
  printf '|---|---|---|---|---|---|\n'
  jq -r '.components[] | select(.ecosystem == "reference") | "| \(.name) | \(.version) | \(.status // "-") | \(.license) | \(.source_url) | \(.adr // "-") |"' "$LOCK"
  printf '\n## Per-component NOTICE files\n\n'
  printf 'Full NOTICE/LICENSE text for components that ship one is under `third-party/NOTICES/`.\n\n'
  # List any NOTICE files present in the NOTICES dir.
  if [ -d third-party/NOTICES ]; then
    for nf in third-party/NOTICES/*; do
      [ -f "$nf" ] || continue
      printf -- '- `%s`\n' "$nf"
    done
  else
    printf -- '- _(no NOTICE files committed yet)_\n'
  fi
  printf '\n---\nGenerated by `make notices` from `third-party/lock.json`.\n'
} > "$OUT"

echo "wrote $OUT"
echo "  components listed: $(jq '.components|length' "$LOCK")"
